use crate::aap::caps::kb_read;

struct Node;

const MAX_QUESTION_CHARS: usize = 512;

/// Truncates to at most `max` Unicode scalar values. This matches Python's `len`
/// on `str` and always cuts on a char boundary.
fn bound_chars(s: &str, max: usize) -> String {
    match s.char_indices().nth(max) {
        Some((idx, _)) => s[..idx].to_string(),
        None => s.to_string(),
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let customer = query.query;

        // The precondition already bounds the question. Enforcing the bound here too
        // guarantees the postcondition for any input.
        let question = bound_chars(&customer.question, MAX_QUESTION_CHARS);

        let mut knowledge: Vec<String> = kb_read::lookup(&question)
            .into_iter()
            .filter(|entry| !entry.trim().is_empty())
            .collect();

        // `present(knowledge)` must hold even when the store has nothing relevant.
        if knowledge.is_empty() {
            knowledge.push(String::from(
                "No relevant knowledge base entries were found for this question.",
            ));
        }

        ConversationContext {
            intent: customer.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
